CREATE TABLE users (id TEXT PRIMARY KEY, phone TEXT NOT NULL UNIQUE, role TEXT NOT NULL DEFAULT 'student' CHECK(role IN ('student','admin')), created_at TEXT NOT NULL);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, stamp TEXT NOT NULL UNIQUE, owner TEXT NOT NULL, user_id TEXT REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE TABLE otp (phone TEXT PRIMARY KEY, digest TEXT NOT NULL, expires_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, sent_at INTEGER NOT NULL);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE content (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('company','event','job','experience')), company_id TEXT REFERENCES content(id), state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','pending','published','offline')), version INTEGER NOT NULL DEFAULT 1, confirmed_version INTEGER, confirmation TEXT NOT NULL DEFAULT '', demo INTEGER NOT NULL DEFAULT 0 CHECK(demo IN (0,1)), data TEXT NOT NULL CHECK(json_valid(data)), updated_at TEXT NOT NULL);
CREATE INDEX content_kind ON content(kind,state);
CREATE TABLE favorites (owner TEXT NOT NULL REFERENCES users(id), content_id TEXT NOT NULL REFERENCES content(id), created_at TEXT NOT NULL, PRIMARY KEY(owner,content_id));
CREATE TABLE drafts (owner TEXT NOT NULL, content_id TEXT NOT NULL REFERENCES content(id), version INTEGER NOT NULL, content_version INTEGER NOT NULL, answers TEXT NOT NULL CHECK(json_valid(answers)), conflict INTEGER NOT NULL DEFAULT 0, saved_at TEXT NOT NULL, PRIMARY KEY(owner,content_id));
CREATE TABLE recoveries (id TEXT PRIMARY KEY, owner TEXT NOT NULL, content_id TEXT NOT NULL REFERENCES content(id), content_version INTEGER NOT NULL, answers TEXT NOT NULL CHECK(json_valid(answers)), reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE submissions (id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES users(id), content_id TEXT NOT NULL REFERENCES content(id), content_version INTEGER NOT NULL, snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), answers TEXT NOT NULL CHECK(json_valid(answers)), created_at TEXT NOT NULL, UNIQUE(owner,content_id,content_version));
CREATE TABLE reports (id TEXT PRIMARY KEY, content_id TEXT NOT NULL REFERENCES content(id), owner TEXT NOT NULL, reason TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','resolved')), resolution TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, resolved_by TEXT REFERENCES users(id), resolved_at TEXT);
CREATE TABLE audit (id INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT NOT NULL, action TEXT NOT NULL, content_id TEXT, details TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE clicks (id INTEGER PRIMARY KEY AUTOINCREMENT, content_id TEXT NOT NULL REFERENCES content(id), owner TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('demo_apply','click_apply','event_click')), created_at TEXT NOT NULL);
